insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1203, 'Tram Capacity', 'A tram stops at n stops in order. At stop i, first a_i passengers get off and then b_i passengers get on. The tram is empty before the first stop, and everyone gets off at the last stop. What is the smallest capacity the tram needs, that is, the largest number of passengers inside it at any moment?', 'The first line contains n (2 ≤ n ≤ 1000). Each of the next n lines contains a_i and b_i (0 ≤ a_i, b_i ≤ 1000). Nobody gets off who is not on the tram, a_1 = 0, and at the last stop b_n = 0 and everyone gets off.', 'Print the required capacity.', '', '[{"input":"4\n0 3\n2 5\n4 2\n4 0\n","output":"6"},{"input":"2\n0 0\n0 0\n","output":"0"}]'::jsonb, array['implementation']::text[], 1000, 2000, 'public') on conflict (id) do nothing;
