insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1204, 'Alarm Clock', 'It is HH:MM now, and the alarm rings in m minutes. What time will the clock show then? The clock uses the 24-hour format and goes from 23:59 to 00:00.', 'The first line contains the time as HH:MM (00 ≤ HH ≤ 23, 00 ≤ MM ≤ 59). The second line contains m (0 ≤ m ≤ 10^9).', 'Print the time in the same HH:MM format.', '', '[{"input":"23:30\n45\n","output":"00:15"},{"input":"08:05\n1440\n","output":"08:05"}]'::jsonb, array['math','implementation']::text[], 1000, 2000, 'public') on conflict (id) do nothing;
