insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1207, 'Flip a Segment', 'A row of coins lies on the table; each coin shows heads `H` or tails `T`. You may choose one block of neighbouring coins and turn all of them over (heads become tails and tails become heads). You may also choose not to turn anything. What is the largest possible number of heads?', 'One line with a string of `H` and `T`, length 1 to 2·10^4.', 'Print the maximum number of heads.', '', '[{"input":"HTTH\n","output":"4"},{"input":"HHH\n","output":"3"},{"input":"TTHT\n","output":"3"}]'::jsonb, array['dp','greedy']::text[], 1200, 2000, 'public') on conflict (id) do nothing;
