insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1209, 'Spiral Walk', 'A snail crawls over an n × m table, starting in the top-left cell. It moves right along the top edge, then down, then left, then up, and so on, turning inwards every time it reaches the edge of the table or a cell it has already visited, until it has visited every cell. Print the numbers in the order the snail visits them.', 'The first line contains n and m (1 ≤ n, m ≤ 100). The next n lines contain m integers each (0 ≤ value ≤ 10^9).', 'Print all n·m numbers on one line, separated by spaces.', '', '[{"input":"3 3\n1 2 3\n4 5 6\n7 8 9\n","output":"1 2 3 6 9 8 7 4 5"},{"input":"2 4\n1 2 3 4\n5 6 7 8\n","output":"1 2 3 4 8 7 6 5"}]'::jsonb, array['implementation']::text[], 1200, 2000, 'public') on conflict (id) do nothing;
